:root {
  --bg-ticket: #1a1a2e;
  --bg-header: #16213e;
  --bg-footer: #0f0f23;
  --accent-gold: #f0c040;
  --accent-teal: #3ecfcf;
  --accent-pink: #e84393;
  --text-primary: #eef0f8;
  --text-muted: #8890b0;
  --record-dark: #111118;
  --record-groove: #2a2a3e;
  --record-label: #c0392b;
  --stage-done: #3ecfcf;
  --stage-active: #f0c040;
  --stage-idle: #3a3a55;
  --divider: #2e2e4a;
}

.ticket {
  width: 480px;
  background: var(--bg-ticket);
  border-radius: 14px;
  overflow: hidden;
  border: 1.5px solid var(--divider);
  margin: 0 auto;
}

.ticket-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-bottom: 1.5px solid var(--divider);
}

.plant-logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  font-size: 28px;
  color: var(--accent-teal);
  line-height: 1;
}

.logo-text {
  display: flex;
  flex-direction: column;
}

.logo-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.04em;
}

.logo-sub {
  font-size: 10px;
  color: var(--text-muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.order-badge {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.badge-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.badge-num {
  font-size: 16px;
  font-weight: 700;
  color: var(--accent-gold);
  letter-spacing: 0.05em;
}

.ticket-body {
  padding: 16px 18px 12px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.track-info {
  display: flex;
  align-items: center;
  gap: 18px;
}

.record-outer {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: var(--record-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  border: 3px solid var(--record-groove);
  flex-shrink: 0;
}

.record-mid {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: var(--record-groove);
  display: flex;
  align-items: center;
  justify-content: center;
}

.record-label {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--record-label);
  display: flex;
  align-items: center;
  justify-content: center;
}

.record-speed {
  font-size: 7px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.release-details {
  flex: 1;
}

.release-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 2px;
}

.release-artist {
  font-size: 12px;
  color: var(--accent-teal);
  margin: 0 0 8px;
  font-weight: 500;
}

.release-specs {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.release-specs li {
  display: flex;
  gap: 8px;
  font-size: 12px;
}

.spec-key {
  color: var(--text-muted);
  min-width: 48px;
}

.spec-val {
  color: var(--text-primary);
  font-weight: 600;
}

.stages {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 8px 4px 4px;
}

.stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  flex: 1;
}

.stage-dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--stage-idle);
  border: 2px solid var(--stage-idle);
}

.stage.done .stage-dot {
  background: var(--stage-done);
  border-color: var(--stage-done);
}

.stage.active .stage-dot {
  background: var(--stage-active);
  border-color: var(--stage-active);
}

.stage-name {
  font-size: 10px;
  color: var(--text-muted);
  font-weight: 500;
  text-align: center;
}

.stage.done .stage-name {
  color: var(--stage-done);
}

.stage.active .stage-name {
  color: var(--stage-active);
  font-weight: 700;
}

.stage-line {
  height: 2px;
  flex: 1;
  background: var(--stage-idle);
  margin-bottom: 15px;
}

.ticket-footer {
  background: var(--bg-footer);
  display: flex;
  justify-content: space-between;
  padding: 10px 18px;
  border-top: 1.5px solid var(--divider);
}

.footer-col {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.foot-label {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-muted);
  font-weight: 600;
}

.foot-val {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.foot-val.highlight {
  color: var(--accent-gold);
  font-size: 15px;
  font-weight: 700;
}
